// deliver.mjs — alternate deliverables for a film (run from repo root):
//   bun studio/tools/deliver.mjs --project 002-ink-and-ember
//
// Produces, into public/film/:
//   <slug>.en.srt                 sidecar captions (copied from the project,
//                                 generated by studio/tools/srt.mjs)
//   <slug>-16x9.mp4               16:9 paper-extension master (1920×1080) —
//                                 the SAME paper world and camera rail re-framed
//                                 to a taller canvas (no bars, no crop)
//   stills/<slug>-{hook,everything,remember}.png
//                                 key stills at design resolution
//
// Vertical alternates (4:5 / 9:16) are deliberately NOT generated: the boards
// are composed for wide frames; cropping beheads heroes. Rendering a vertical
// variant requires a re-authored rail and zone layout — not a flag.
//
// The 16:9 master is grade-matched to the primary build (same plain-fade
// pipeline as the project's build.mjs — vignette/grain defaults included via
// engine/compose.mjs). Chunks render sequentially (OOM law); every part is
// probed before concat (LAW 3); the published file goes through the
// FINAL-FILE LAW probe.
import { mkdirSync, copyFileSync, rmSync, existsSync, writeFileSync } from 'node:fs';
import { join, resolve, dirname } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { createCanvas } from '@napi-rs/canvas';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');
const arg = (name) => {
  const i = process.argv.indexOf(name);
  return i >= 0 ? process.argv[i + 1] : null;
};
const project = arg('--project');
if (!project) {
  console.error('usage: bun studio/tools/deliver.mjs --project <slug>');
  process.exit(2);
}
const PROJ = join(ROOT, 'studio/projects', project);
if (!existsSync(join(PROJ, 'timings.mjs'))) {
  console.error(`project not found: ${PROJ}`);
  process.exit(2);
}
const { T } = await import(pathToFileURL(join(PROJ, 'timings.mjs')).href);
const { drawWorld } = await import(pathToFileURL(join(PROJ, 'world.mjs')).href);
const { renderFrame, renderChunkFrames } = await import(pathToFileURL(join(ROOT, 'studio/engine/compose.mjs')).href);
const { concatParts, muxAndPublish } = await import(pathToFileURL(join(ROOT, 'studio/engine/buildlib.mjs')).href);

// plain-fade grade — mirrors the project build.mjs (compose applies default
// vignette/grain when not overridden, which is what the 21:9 master ships with)
const GRADE = { fade: { fadeIn: T.fadeIn, fadeOut: T.fadeOut } };
const slug = project;

// ── 1) 16:9 paper-extension master ─────────────────────────────────────────
const DESIGN = { W: 1920, H: 1080 };
const T16 = { ...T, ...DESIGN };
const OUT16 = join(PROJ, 'out', '16x9');
mkdirSync(OUT16, { recursive: true });
mkdirSync(join(ROOT, 'public/film'), { recursive: true });
mkdirSync(join(ROOT, 'public/film/stills'), { recursive: true });

const CHUNK = 244;
for (let start = 0; start < T16.FRAMES; start += CHUNK) {
  const end = Math.min(T16.FRAMES, start + CHUNK);
  const partPath = join(OUT16, `part_${String(start).padStart(4, '0')}.mp4`);
  rmSync(partPath, { force: true });
  await renderChunkFrames({
    T: T16, drawWorld, grade: GRADE, start, end, outPath: partPath, quality: 'master',
  });
  console.log(`[deliver] 16x9 chunk [${start}, ${end}) done`);
}
const videoOnly = join(OUT16, 'video-only.mp4');
await concatParts(slug, { dir: OUT16 });
const pub16 = await muxAndPublish(slug, {
  mixWav: join(PROJ, 'out', 'mix.wav'),
  frames: T16.FRAMES, dur: T16.DUR, fps: T16.FPS,
  publishAs: `${slug}-16x9.mp4`, dir: OUT16,
});
console.log(`[deliver] published → ${pub16}`);

// ── 2) key stills (design resolution, same grade as the master) ────────────
const STILLS = [
  { name: 'hook', t: 1.75 },
  { name: 'everything', t: 21.0 },
  { name: 'remember', t: 24.05 },
];
for (const { name, t } of STILLS) {
  const canvas = createCanvas(T.W, T.H);
  const ctx = canvas.getContext('2d');
  renderFrame(ctx, T.W, T.H, t, drawWorld, { rail: T.rail, grade: GRADE, design: { W: T.W, H: T.H } });
  const dest = join(ROOT, 'public/film/stills', `${slug}-${name}.png`);
  writeFileSync(dest, await canvas.encode('png'));
  console.log(`[deliver] still → ${dest}`);
}

// ── 3) SRT sidecar copy ────────────────────────────────────────────────────
const srtSrc = join(PROJ, 'assets', 'subtitles.en.srt');
const srtDst = join(ROOT, 'public/film', `${slug}.en.srt`);
if (existsSync(srtSrc)) {
  copyFileSync(srtSrc, srtDst);
  console.log(`[deliver] captions → ${srtDst}`);
} else {
  console.log(`[deliver] no subtitles.en.srt in project — skip captions copy (bun studio/tools/srt.mjs first)`);
}
console.log('[deliver] done');
